<?php
/**
 * Custom PHP fatal-error template for WordPress.com Atomic sites.
 *
 * Generated by WordPress.com Site Helper.
 * This file is copied to wp-content/php-error.php by wpcomsh so WordPress
 * fully delegates fatal-error rendering to this template instead of the
 * default `WP_Fatal_Error_Handler::display_default_error_template()` output.
 *
 * @package wpcomsh
 */

if ( ! function_exists( 'wpcomsh_php_error_esc_html' ) ) {
	/**
	 * Escape text for safe HTML output even in early bootstrap.
	 *
	 * @param string $text Text to escape.
	 * @return string
	 */
	function wpcomsh_php_error_esc_html( $text ) {
		if ( function_exists( 'esc_html' ) ) {
			return esc_html( $text );
		}

		return htmlspecialchars( $text, ENT_QUOTES, 'UTF-8' );
	}
}

if ( ! function_exists( 'wpcomsh_php_error_esc_url' ) ) {
	/**
	 * Escape a URL for safe output even when `esc_url()` is unavailable.
	 *
	 * @param string $url URL to escape.
	 * @return string
	 */
	function wpcomsh_php_error_esc_url( $url ) {
		if ( function_exists( 'esc_url' ) ) {
			return esc_url( $url );
		}

		return htmlspecialchars( $url, ENT_QUOTES, 'UTF-8' );
	}
}

if ( ! function_exists( 'wpcomsh_get_php_error_screen_data' ) ) {
	/**
	 * Build the copy shown on the fatal-error screen.
	 *
	 * @param true|WP_Error $handled               Whether Recovery Mode handled the fatal error.
	 * @param bool|null     $is_protected_endpoint Optional. Whether the request is a protected endpoint.
	 * @param bool|null     $is_multisite          Optional. Whether the site is multisite.
	 * @param bool|null     $is_recovery_mode      Optional. Whether the site is in recovery mode.
	 * @return array{heading:string,body:string,show_support_forums:bool}
	 */
	function wpcomsh_get_php_error_screen_data( $handled, $is_protected_endpoint = null, $is_multisite = null, $is_recovery_mode = null ) {
		if ( null === $is_multisite ) {
			$is_multisite = function_exists( 'is_multisite' ) && is_multisite();
		}

		if ( null === $is_recovery_mode ) {
			$is_recovery_mode = function_exists( 'wp_is_recovery_mode' ) && wp_is_recovery_mode();
		}

		if ( null === $is_protected_endpoint ) {
			$is_protected_endpoint = function_exists( 'is_protected_endpoint' )
				&& function_exists( 'wp_recovery_mode' )
				&& is_protected_endpoint()
				&& wp_recovery_mode()->is_initialized();
		}

		$generic_message = function_exists( '__' )
			// phpcs:ignore WordPress.WP.I18n.TextDomainMismatch -- Verbatim WP core string to reuse early-loaded core translations.
			? __( 'There has been a critical error on this website.', 'default' )
			: 'There has been a critical error on this website.';

		$data = array(
			'heading'             => $generic_message,
			'body'                => $generic_message,
			'show_support_forums' => false,
		);

		if ( true === $handled && $is_recovery_mode ) {
			$data['body'] = function_exists( '__' )
				// phpcs:ignore WordPress.WP.I18n.TextDomainMismatch -- Verbatim WP core string to reuse early-loaded core translations.
				? __( 'There has been a critical error on this website, putting it in recovery mode. Please check the Themes and Plugins screens for more details. If you just installed or updated a theme or plugin, check the relevant page for that first.', 'default' )
				: 'There has been a critical error on this website, putting it in recovery mode. Please check the Themes and Plugins screens for more details. If you just installed or updated a theme or plugin, check the relevant page for that first.';
			return $data;
		}

		if ( $is_protected_endpoint ) {
			if ( $is_multisite ) {
				$data['body'] = function_exists( '__' )
					// phpcs:ignore WordPress.WP.I18n.TextDomainMismatch -- Verbatim WP core string to reuse early-loaded core translations.
					? __( 'There has been a critical error on this website. Please reach out to your site administrator, and inform them of this error for further assistance.', 'default' )
					: 'There has been a critical error on this website. Please reach out to your site administrator, and inform them of this error for further assistance.';
				return $data;
			}

			$data['body'] = function_exists( '__' )
				// phpcs:ignore WordPress.WP.I18n.TextDomainMismatch -- Verbatim WP core string to reuse early-loaded core translations.
				? __( 'There has been a critical error on this website. Please check your site admin email inbox for instructions.', 'default' )
				: 'There has been a critical error on this website. Please check your site admin email inbox for instructions.';
			$data['show_support_forums'] = true;
		}

		return $data;
	}
}

if ( ! function_exists( 'wpcomsh_render_php_error_template' ) ) {
	/**
	 * Render the WordPress.com fatal-error screen.
	 *
	 * @param array         $error   Error information retrieved from `error_get_last()`.
	 * @param true|WP_Error $handled Whether Recovery Mode handled the fatal error.
	 * @return void
	 */
	function wpcomsh_render_php_error_template( $error, $handled ) {
		unset( $error );

		if ( ! function_exists( '__' ) && function_exists( 'wp_load_translations_early' ) ) {
			wp_load_translations_early();
		}

		if ( ! headers_sent() ) {
			if ( function_exists( 'status_header' ) ) {
				status_header( 500 );
			} else {
				header( 'HTTP/1.1 500 Internal Server Error', true, 500 );
			}

			if ( function_exists( 'nocache_headers' ) ) {
				nocache_headers();
			} else {
				header( 'Cache-Control: no-cache, must-revalidate, max-age=0' );
				header( 'Expires: Wed, 11 Jan 1984 05:00:00 GMT' );
			}
		}

		$data                = wpcomsh_get_php_error_screen_data( $handled );
		$troubleshooting_url = 'https://wordpress.com/support/plugins/troubleshooting/';
		$support_forums_url  = 'https://wordpress.com/forums/';

		if ( function_exists( 'localized_wpcom_url' ) ) {
			$troubleshooting_url = localized_wpcom_url( $troubleshooting_url );
			$support_forums_url  = localized_wpcom_url( $support_forums_url );
		}

		$heading = wpcomsh_php_error_esc_html( $data['heading'] );
		$body    = wpcomsh_php_error_esc_html( $data['body'] );
		?>
<?php // phpcs:disable WordPress.Security.EscapeOutput.OutputNotEscaped -- All dynamic values in this template are escaped before output. ?>
<!doctype html>
<html lang="en">
	<head>
		<meta charset="utf-8">
		<meta name="viewport" content="width=device-width, initial-scale=1">
		<title><?php echo $heading; ?></title>
		<style>
			html {
				font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
				line-height: 1.5;
				color: #101517;
				background: #eef3ef;
			}

			body {
				margin: 0;
				padding: 32px 20px;
			}

			.wpcomsh-fatal-error {
				max-width: 720px;
				margin: 0 auto;
				padding: 32px 28px;
				border-radius: 20px;
				background: #fff;
				box-shadow: 0 18px 50px rgba(16, 21, 23, 0.08);
			}

			.wpcomsh-fatal-error__eyebrow {
				margin: 0 0 12px;
				font-size: 12px;
				font-weight: 700;
				letter-spacing: 0.08em;
				text-transform: uppercase;
				color: #3858e9;
			}

			.wpcomsh-fatal-error__heading {
				margin: 0 0 16px;
				font-size: 32px;
				line-height: 1.15;
			}

			.wpcomsh-fatal-error__body {
				margin: 0 0 24px;
				font-size: 17px;
				color: #50575e;
			}

			.wpcomsh-fatal-error__links {
				display: flex;
				flex-wrap: wrap;
				gap: 12px;
			}

			.wpcomsh-fatal-error__link {
				display: inline-flex;
				align-items: center;
				justify-content: center;
				padding: 12px 16px;
				border-radius: 999px;
				background: #101517;
				color: #fff;
				font-weight: 600;
				text-decoration: none;
			}

			.wpcomsh-fatal-error__link--secondary {
				background: #eef3ef;
				color: #101517;
			}
		</style>
	</head>
	<body>
		<main class="wpcomsh-fatal-error">
			<p class="wpcomsh-fatal-error__eyebrow">WordPress.com</p>
			<h1 class="wpcomsh-fatal-error__heading"><?php echo $heading; ?></h1>
			<p class="wpcomsh-fatal-error__body"><?php echo $body; ?></p>
			<div class="wpcomsh-fatal-error__links">
				<a class="wpcomsh-fatal-error__link" href="<?php echo wpcomsh_php_error_esc_url( $troubleshooting_url ); ?>">
					<?php echo wpcomsh_php_error_esc_html( 'Learn more about troubleshooting WordPress.com.' ); ?>
				</a>
				<?php if ( $data['show_support_forums'] ) : ?>
					<a class="wpcomsh-fatal-error__link wpcomsh-fatal-error__link--secondary" href="<?php echo wpcomsh_php_error_esc_url( $support_forums_url ); ?>">
						<?php echo wpcomsh_php_error_esc_html( 'WordPress.com support forums' ); ?>
					</a>
				<?php endif; ?>
			</div>
		</main>
	</body>
</html>
<?php // phpcs:enable WordPress.Security.EscapeOutput.OutputNotEscaped ?>
		<?php
	}
}

// phpcs:ignore VariableAnalysis.CodeAnalysis.VariableAnalysis.UndefinedVariable -- `$error` and `$handled` are provided by WP_Fatal_Error_Handler when this template is included from wp-content/php-error.php.
if ( isset( $error ) ) {
	// phpcs:ignore VariableAnalysis.CodeAnalysis.VariableAnalysis.UndefinedVariable -- `$error` and `$handled` are provided by WP_Fatal_Error_Handler when this template is included from wp-content/php-error.php.
	wpcomsh_render_php_error_template( $error, $handled ?? false );
}
